-- Convert the retired preset IDs to readable copy once; runtime artwork uses only labels.
DO $migration$
DECLARE
  labels jsonb := $labels${"free-entry": {"en": "Free", "fr": "Entrée Gratuite"}, "free-food": {"en": "Free Food", "fr": "Repas Gratuit"}, "happening-today": {"en": "Happening Today", "fr": "Aujourd’Hui"}, "tomorrow-s-plan": {"en": "Tomorrow’S Plan", "fr": "Demain"}, "this-weekend": {"en": "This Weekend", "fr": "Ce Week-End"}, "food-available": {"en": "Food Available", "fr": "À Manger Sur Place"}, "bring-a-friend": {"en": "Bring A Friend", "fr": "Viens Avec Un Ami"}, "campus-pick": {"en": "Campus Pick", "fr": "À Découvrir"}, "after-class-plans": {"en": "After Class Plans", "fr": "Après Les Cours"}, "see-you-there": {"en": "See You There", "fr": "On S’Y Retrouve"}, "save-the-date": {"en": "Save The Date", "fr": "À Vos Agendas"}, "try-something-new": {"en": "Try New Things", "fr": "Essaie Autre Chose"}, "make-a-memory": {"en": "Make A Memory", "fr": "Un Bon Souvenir"}, "meet-your-people": {"en": "Meet Your People", "fr": "Trouve Ta Communauté"}, "group-chat-plans": {"en": "Group Chat Plans", "fr": "À Partager"}, "worth-a-look": {"en": "Worth A Look", "fr": "Ça Vaut Le Détour"}, "your-next-plan": {"en": "Your Next Plan", "fr": "Ta Prochaine Sortie"}, "campus-vibes": {"en": "Campus Vibes", "fr": "Ambiance Campus"}, "robotics": {"en": "Robotics", "fr": "Robotique"}, "ai-curious": {"en": "Ai Curious", "fr": "Curieux D’Ia"}, "code-together": {"en": "Code Together", "fr": "Codons Ensemble"}, "hackathon": {"en": "Hackathon", "fr": "Hackathon"}, "build-something": {"en": "Build Something", "fr": "Crée Quelque Chose"}, "game-night": {"en": "Game Night", "fr": "Soirée Jeux"}, "board-games": {"en": "Board Games", "fr": "Jeux De Société"}, "video-games": {"en": "Video Games", "fr": "Jeux Vidéo"}, "chess-club": {"en": "Chess Club", "fr": "Échecs"}, "trivia-time": {"en": "Trivia Time", "fr": "Quiz"}, "movie-night": {"en": "Movie Night", "fr": "Soirée Cinéma"}, "live-music": {"en": "Live Music", "fr": "Musique En Direct"}, "open-mic": {"en": "Open Mic", "fr": "Micro Ouvert"}, "karao