BEGIN
  UPDATE public.instagram_publish_batches AS batch
  SET sticker_selections = (
    SELECT jsonb_object_agg(entry.key, (
      SELECT coalesce(jsonb_agg(coalesce(
        labels -> item.label ->> CASE WHEN school.language = 'fr' THEN 'fr' ELSE 'en' END,
        item.label
      ) ORDER BY item.position), '[]'::jsonb)
      FROM jsonb_array_elements_text(entry.value) WITH ORDINALITY AS item(label, position)
    ))
    FROM jsonb_each(batch.sticker_selections) AS entry
  ), version = batch.version + 1
  FROM public.schools AS school
  WHERE school.id = batch.school_id
    AND EXISTS (
      SELECT 1 FROM jsonb_each(batch.sticker_selections) AS entry,
      LATERAL jsonb_array_elements_text(entry.value) AS item(label)
      WHERE labels ? item.label
    );
END;
$migration$;
